def solve():
    wa = Fraction(P["W_A"])
    wb = Fraction(P["W_B"])
    wc = Fraction(P["W_C"])
    wd = 100 - wa - wb - wc
    if wd < 1:
        raise ValueError("remainder weight for D below 1 percent")
    names = ["A", "B", "C", "D"]
    weights = {"A": wa / 100, "B": wb / 100, "C": wc / 100, "D": wd / 100}
    scores = {"A": Fraction(P["S_A"]), "B": Fraction(P["S_B"]), "C": Fraction(P["S_C"]), "D": Fraction(P["S_D"])}
    avg = sum(weights[n] * scores[n] for n in names)
    floor = Fraction(1, 4)
    factors = {}
    for n in names:
        f = 1 + 2 * (scores[n] - avg) / 100
        if f < floor:
            f = floor
        factors[n] = f
    raw = {n: weights[n] * factors[n] for n in names}
    total = sum(raw[n] for n in names)
    new = {n: raw[n] / total for n in names}
    port_score = sum(new[n] * scores[n] for n in names)
    t = P["TARGET"]
    final = new[t] * 100
    active = final - weights[t] * 100
    return {"final": final, "benchmark_avg_score": avg, "tilted_portfolio_score": port_score, "active_weight_pp": active}
